/// <summary>
///     Extension class for InventTransferShipReceiveController
/// </summary>
[ExtensionOf(classStr(InventTransferShipReceiveController))]
final class AVAInventTransferShipReceiveControllerCls_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>getReportName</c> method.
/// </summary>
/// <returns>
///     <c>str</c> as return value
/// </returns>
public str getReportName()
{
    str strReportName;

    strReportName = next getReportName();

    if (this.parmArgs().parmEnum() == InventTransferUpdateType::Receive
        &&  strReportName == ssrsReportStr(InventTransferReceive, Report))
    {
        strReportName = ssrsReportStr(AVAInventTransferReceive, Report);
    }
    else if (   this.parmArgs().parmEnum() == InventTransferUpdateType::Shipment
            && strReportName == ssrsReportStr(InventTransferShip, Report))
    {
        strReportName = ssrsReportStr(AVAInventTransferShip, Report);
    }

    return strReportName;
}

/// <summary>
///     AVA <c>parmReportName</c> method.
/// </summary>
/// <param name="_reportName">
///     <c>SRSCatalogItemName</c> as type
/// </param>
/// <returns>
///     <c>SRSCatalogItemName</c> as return value
/// </returns>
public SRSCatalogItemName parmReportName(SRSCatalogItemName _reportName)
{
    SRSCatalogItemName retVal;

    retVal = next parmReportName(_reportName);

    if (retVal == ssrsReportStr(InventTransferReceive, Report))
    {
        retVal = ssrsReportStr(AVAInventTransferReceive, Report);
    }
    else if (retVal == ssrsReportStr(InventTransferShip, Report))
    {
        retVal = ssrsReportStr(AVAInventTransferShip, Report);
    }

    return retVal;
}
